#!/usr/bin/env python3
import os
from PIL import Image
import pytesseract

# 设置Tesseract路径
pytesseract.pytesseract.tesseract_cmd = '/opt/homebrew/bin/tesseract'

def analyze_image(image_path):
    """分析图片内容"""
    print(f"\n分析图片: {os.path.basename(image_path)}")

    try:
        # 打开图片
        img = Image.open(image_path)
        print(f"图片尺寸: {img.size}")
        print(f"图片模式: {img.mode}")

        # 尝试不同的OCR配置
        configs = [
            ("自动", "--psm 3 -l chi_sim+eng"),
            ("单行", "--psm 6 -l chi_sim+eng"),
            ("稀疏文本", "--psm 11 -l chi_sim+eng"),
            ("稀疏文本+方向", "--psm 12 -l chi_sim+eng"),
        ]

        best_text = ""
        best_len = 0

        for name, config in configs:
            try:
                text = pytesseract.image_to_string(img, config=config)
                text = text.strip()
                if text and len(text) > best_len:
                    best_len = len(text)
                    best_text = text
                print(f"\n{name}配置提取到 {len(text)} 字符")
                if text:
                    lines = text.split('\n')
                    for i, line in enumerate(lines[:10]):
                        if line.strip():
                            print(f"  {i+1}: {line[:80]}{'...' if len(line) > 80 else ''}")
                    if len(lines) > 10:
                        print(f"  ... 还有 {len(lines)-10} 行")
            except Exception as e:
                print(f"{name}配置出错: {e}")

        return best_text

    except Exception as e:
        print(f"处理图片出错: {e}")
        return ""

def main():
    desktop = os.path.expanduser("~/Desktop")

    images = [
        "彪哥战法_四季分析.png",
        "彪哥战法_四季判断分析.png",
        "彪哥战法_实战仪表盘.png",
        "彪哥战法_明日策略_0302.png"
    ]

    results = {}

    for img_name in images:
        img_path = os.path.join(desktop, img_name)
        if os.path.exists(img_path):
            text = analyze_image(img_path)
            results[img_name] = text
            print("\n" + "="*80)
        else:
            print(f"文件不存在: {img_path}")

    # 总结关键信息
    print("\n" + "="*80)
    print("关键内容总结")
    print("="*80)

    for img_name, text in results.items():
        if text:
            # 提取看起来像中文或重要信息的部分
            lines = text.split('\n')
            important_lines = []
            for line in lines:
                line = line.strip()
                if len(line) > 3:  # 过滤太短的行
                    # 检查是否包含中文字符或数字
                    has_chinese = any('\u4e00' <= char <= '\u9fff' for char in line)
                    has_numbers = any(char.isdigit() for char in line)
                    if has_chinese or has_numbers:
                        important_lines.append(line)

            if important_lines:
                print(f"\n{img_name}:")
                for i, line in enumerate(important_lines[:5]):
                    print(f"  {line[:100]}{'...' if len(line) > 100 else ''}")

if __name__ == "__main__":
    main()
